func TestUnifiedDiff_ModifiedLine(t *testing.T) {
	before := "{\n  \"name\": \"demo\",\n  \"version\": \"0.1.0\"\n}\n"
	after := "{\n  \"name\": \"demo\",\n  \"version\": \"0.2.0\"\n}\n"

	got := UnifiedDiff("package.json", before, after)
	if !strings.Contains(got, "--- a/package.json\n+++ b/package.json\n") {
		t.Fatalf("missing diff header:\n%s", got)
	}
	if !strings.Contains(got, "-\"version\": \"0.1.0\"") && !strings.Contains(got, "-  \"version\": \"0.1.0\"") {
		t.Fatalf("missing removed version line:\n%s", got)
	}
	if !strings.Contains(got, "+  \"version\": \"0.2.0\"") {
		t.Fatalf("missing added version line:\n%s", got)
	}
}

func TestUnifiedDiff_IdenticalReturnsEmpty(t *testing.T) {
	content := "version = \"1.0.0\"\n"
	if got := UnifiedDiff("Cargo.toml", content, content); got != "" {
		t.Fatalf("expected empty diff for identical content, got %q", got)
	}
}

func TestUnifiedDiffBytes(t *testing.T) {
	got := UnifiedDiffBytes("./Chart.yaml", []byte("version: 0.1.0\n"), []byte("version: 0.2.0\n"))
	if !strings.Contains(got, "--- a/Chart.yaml\n+++ b/Chart.yaml\n") {
		t.Fatalf("unexpected header in:\n%s", got)
	}
	if !strings.Contains(got, "-version: 0.1.0\n+version: 0.2.0\n") {
		t.Fatalf("unexpected body in:\n%s", got)
	}
}

